using System;using System.IO;using System.Linq;using System.Text;using System.Security.Cryptography;using IdleIntelligence.Core;using IdleIntelligence.Runtime;using NUnit.Framework;using UnityEngine;
namespace IdleIntelligence.Tests {
 public sealed class SnapshotMigrationTests {
 [Serializable]sealed class TextValue{public string value;}
 static string Quote(string s){string json=JsonUtility.ToJson(new TextValue{value=s});return json.Substring(9,json.Length-10);}
 static string Json(SaveJsonValidation.Value v){if(v.Kind=="object")return "{"+string.Join(",",v.Fields.Select(p=>Quote(p.Key)+":"+Json(p.Value)))+"}";if(v.Kind=="array")return "["+string.Join(",",v.Items.Select(Json))+"]";if(v.Kind=="string")return Quote(v.Text);return v.Kind=="null"?"null":v.Text;}
 [Test]public void NativeImportRetainsOriginalBomAndCrLfTransportBytes(){var transfer=JsonUtility.FromJson<WebTransfer>(File.ReadAllText(Path.Combine(Application.dataPath,"IdleIntelligence/Tests/EditMode/WebImportReferenceCase.json")));transfer.original="\uFEFF{\r\n"+transfer.original.Substring(1);var state=UnityWebImport.Validate(JsonUtility.ToJson(transfer));Assert.That(state.Web.original,Is.EqualTo(transfer.original));Assert.That(Encoding.UTF8.GetBytes(state.Web.original),Is.EqualTo(Encoding.UTF8.GetBytes(transfer.original)));}
 [TestCase(false)][TestCase(true)]public void V19ArchivedClassUpgradeKeepsChallengeAndReturnedMainContexts(bool returned){string transfer=File.ReadAllText(Path.Combine(Application.dataPath,"IdleIntelligence/Tests/EditMode/ActiveWebImportReference.json"));var current=UnityWebImport.Validate(transfer);Assert.That(current.Challenges.Main.Legacy.classUpgrades,Does.Contain("calculator"));if(returned)current=ChallengeRules.Return(current,false);var codec=new UnitySaveCodec();var tree=SaveJsonValidation.Parse(codec.Encode(StateData.From(current)));void Old(SaveJsonValidation.Value v){v.Field("legacy").Fields.Remove("classUpgrades");v.Field("legacy").Fields.Remove("classUpgradesRecorded");}Old(tree);if(!returned)Old(tree.Field("challengeMain"));var decoded=codec.Decode(Json(tree),19).ToState();if(!returned){Assert.That(decoded.Legacy.classUpgrades,Is.Empty);decoded=ChallengeRules.Return(decoded,false);}Assert.That(decoded.Legacy.classUpgrades,Does.Contain("calculator"));Assert.That(Game.Compute(decoded).CompareTo(Game.Compute(returned?current:ChallengeRules.Return(current,false))),Is.Zero);}
 [Serializable]sealed class CompatibilityTransfers {public CompatibilityTransfer[] rows;}[Serializable]sealed class CompatibilityTransfer{public string transfer;}
 [Test]public void V19RestoresUnambiguousArchivedClassUpgradeAndKeepsByteExactOriginal(){var cases=JsonUtility.FromJson<CompatibilityTransfers>(File.ReadAllText(Path.Combine(Application.dataPath,"IdleIntelligence/Tests/EditMode/CompatibilityReferenceCases.json")));var state=UnityWebImport.Validate(cases.rows[0].transfer);Assert.That(state.Legacy.classUpgrades,Does.Contain("calculator"));var codec=new UnitySaveCodec();var tree=SaveJsonValidation.Parse(codec.Encode(StateData.From(state)));tree.Field("legacy").Fields.Remove("classUpgrades");tree.Field("legacy").Fields.Remove("classUpgradesRecorded");string payload=Json(tree),hash;using(var sha=SHA256.Create())hash=BitConverter.ToString(sha.ComputeHash(Encoding.UTF8.GetBytes(payload))).Replace("-","").ToLowerInvariant();string raw=codec.EncodeEnvelope(new SaveEnvelope{format=AtomicSaveStore.Format,version=19,payload=payload,sha256=hash});string dir=Path.Combine(Path.GetTempPath(),"unity-v19-class-"+Guid.NewGuid());Directory.CreateDirectory(dir);try{string path=Path.Combine(dir,"save.json");File.WriteAllText(path,raw);var store=new AtomicSaveStore(path,codec);var loaded=store.Load(state.SavedAt);Assert.That(loaded.Writable,Is.True,loaded.Message);Assert.That(loaded.State.Legacy.classUpgrades,Is.EqualTo(state.Legacy.classUpgrades));Assert.That(Game.Compute(loaded.State).CompareTo(Game.Compute(state)),Is.Zero);Assert.That(File.ReadAllText(Directory.GetFiles(dir,"*.v19-original-*").Single()),Is.EqualTo(raw));var reset=PrestigeRules.Reset(loaded.State);Assert.That(reset.Legacy.classUpgrades,Is.Empty);store.Save(loaded.State);Assert.That(codec.DecodeEnvelope(File.ReadAllText(path)).version,Is.EqualTo(20));}finally{Directory.Delete(dir,true);}}
 [Test]public void TransferRejectsChangedResearchModelsAndInventoryContracts(){string raw=File.ReadAllText(Path.Combine(Application.dataPath,"IdleIntelligence/Tests/EditMode/WebImportReferenceCase.json"));var source=JsonUtility.FromJson<WebTransfer>(raw);var codec=new UnitySaveCodec();var actual=UnityWebImport.Validate(raw);actual.Research[0]++;source.payload=codec.Encode(StateData.From(actual));Assert.Throws<FormatException>(()=>UnityWebImport.Validate(JsonUtility.ToJson(source)));}
 [Test]public void PublishedV18IsPreservedAndUnrecordedExactCountersAreNotInvented(){string dir=Path.Combine(Path.GetTempPath(),"unity-v18-snapshot-"+Guid.NewGuid());Directory.CreateDirectory(dir);try{var codec=new UnitySaveCodec();var tree=SaveJsonValidation.Parse(codec.Encode(StateData.From(Game.New(1000000))));foreach(string key in new[]{"runCredits","runCreditsRecorded","lifetimeCreditsExact","lifetimeCreditsExactRecorded","lifetimeEligibleExact","lifetimeEligibleExactRecorded","lifetimeDataExact","lifetimeDataExactRecorded"})tree.Fields.Remove(key);tree.Field("journal").Field("history").Fields.Remove("measurementKnown");string payload=Json(tree),hash;using(var sha=SHA256.Create())hash=BitConverter.ToString(sha.ComputeHash(Encoding.UTF8.GetBytes(payload))).Replace("-","").ToLowerInvariant();string raw=codec.EncodeEnvelope(new SaveEnvelope{format=AtomicSaveStore.Format,version=18,payload=payload,sha256=hash}),path=Path.Combine(dir,"save.json");File.WriteAllText(path,raw);var store=new AtomicSaveStore(path,codec);var load=store.Load(1000000);Assert.That(load.Writable,Is.True,load.Message);Assert.That(load.State.RunCreditsRecorded,Is.False);Assert.That(load.State.LifetimeCreditsExactRecorded,Is.False);Assert.That(File.ReadAllText(Directory.GetFiles(dir,"*.v18-original-*").Single()),Is.EqualTo(raw));store.Save(load.State);Assert.That(codec.DecodeEnvelope(File.ReadAllText(path)).version,Is.EqualTo(20));}finally{Directory.Delete(dir,true);}}
 [Test]public void FullNativePointsKeepEquipmentResearchModelsAndExactRunSeparateFromCycle(){var s=Game.New(1000000);PrestigeRules.Earn(s,ScientificNumber.Parse("1e40"));s=PrestigeRules.Reset(s);var point=BalanceObservation.At(s,true);Assert.That(point.fullRecorded,Is.True);Assert.That(point.runCreditsRecorded,Is.True);Assert.That(ScientificNumber.FromData(point.runCredits).IsZero,Is.True);Assert.That(s.Prestige.Eligible.IsZero,Is.False);Assert.That(point.equipped.Length,Is.EqualTo(8));Assert.That(point.research.Length,Is.EqualTo(Balance.Research.Length));Assert.That(point.modelLevels.Length,Is.EqualTo(10));Assert.That(s.LifetimeCreditsExact.CompareTo(ScientificNumber.Parse("1e40")),Is.Zero);var first=s.Journal.history.runs.Single();Assert.That(first.end.fullRecorded,Is.True);Assert.That(first.checkpoints.All(p=>!p.fullRecorded),Is.True);Game.Validate(s);}
 [Test]public void ActiveImportedChallengeRetainsOriginalAfterAbortSaveAndReload(){string raw=File.ReadAllText(Path.Combine(Application.dataPath,"IdleIntelligence/Tests/EditMode/ActiveWebImportReference.json"));var s=UnityWebImport.Validate(raw);Assert.That(ChallengeRules.Active(s),Is.True);string original=s.Web.original;Assert.That(s.Challenges.Main.Web.original,Is.EqualTo(original));var restored=ChallengeRules.Return(s,false);Assert.That(restored.Web.original,Is.EqualTo(original));var codec=new UnitySaveCodec();var reload=codec.Decode(codec.Encode(StateData.From(restored)),19).ToState();Assert.That(reload.Web.original,Is.EqualTo(original));Assert.That(reload.LifetimeCreditsExactRecorded,Is.True);}
 }
}
